int[] copy = arr.clone();
copy[0] = 9;
System.out.println(arr[0] + " " + copy[0]);

int[][] arr = {{1, 2}};
int[][] copy = arr.clone();
copy[0][0] = 9;
System.out.println(arr[0][0]);

int[] arr = {1, 2, 3};
modify(arr);
System.out.println(arr[0]);
