static void reassign(int[] a) {
    a = new int[]{100, 200, 300};
}

int[] src = {1, 2, 3};
int[] dest = new int[3];
System.arraycopy(src, 1, dest, 0, 2);
System.out.println(dest[0] + " " + dest[1]);

